package models

// ResultStatus represents the status of a result
type ResultStatus string

const (
	ResultStatusSuccess ResultStatus = "success"
	ResultStatusFailure ResultStatus = "failure"
	ResultStatusError   ResultStatus = "error"
)

// ResultSource indicates where a check result originated.
type ResultSource string

const (
	// ResultSourceMonitor means the result comes from an actual monitor check signal.
	ResultSourceMonitor ResultSource = "monitor"
	// ResultSourcePlatform means the result was generated by platform/app logic.
	ResultSourcePlatform ResultSource = "platform"
	// ResultSourceDerived is used for in-memory synthetic/aggregated results.
	ResultSourceDerived ResultSource = "derived"
)
